// T143 S4: the Neo Geo's ROM sets (coreapp/cores/neoset.cc) and descriptor (coreapp/cores/neogeo.cc) against a model of the core's register block, its copy engine and a 128 MB
// DDR2 of which the application's CPU can write only the first 64 MB. Every byte of a synthetic set (generated bytes, no game, no BIOS) is looked for where the core's address
// maps (cores/neogeo/rtl/neogeo.sv ioctl_addr_offset, CROM_LOAD_ADDR, VROM_LOAD_ADDR, the fix data layout of DEV_NOTES.md) put it; a swapped C1/C2 pair, a wrong V space or a
// fix tile in the wrong order is red. The oracles below restate those maps from the Verilog, not from neoset.cc.
#include <vector>
#include <string>
#include "check.h"
#include "fakes.h"
#include "boot.h"
#include "engines.h"
#include "cores.h"
#include "neogeo_regs.h"
#include "neoset.h"
#include "ops_glue.h"

struct NeoIo : FakeIo {
    uint32_t copies = 0;
    bool cpu_over = false, bad_align = false;
    std::vector<uint8_t> mv_cmds;
    NeoIo() { ddr.assign(0x07000000, 0); }                              // window offsets 0 .. 0x06FFFFFF = absolute 0x01000000 .. 0x07FFFFFF
    void ddr_write(uint32_t off, const void *p, uint32_t n) override
    {
        if ((uint64_t)off + n > 0x03000000ull) { cpu_over = true; return; }   // the CPU reaches 64 MB, the window starts at 16 MB
        memcpy(&ddr[off], p, n);
    }
    void ddr_read(uint32_t off, void *p, uint32_t n) override
    {
        if ((uint64_t)off + n > 0x03000000ull) { cpu_over = true; memset(p, 0, n); return; }
        memcpy(p, &ddr[off], n);
    }
    uint32_t r32(uint32_t reg) const { return regs[reg] | regs[reg + 1] << 8 | regs[reg + 2] << 16 | (uint32_t)regs[reg + 3] << 24; }
    uint8_t at(uint32_t abs) const { return ddr.at(abs - 0x01000000u); }
    void on_wr(uint32_t reg, uint8_t) override
    {
        if (reg != NEO_MV_GO) return;
        uint8_t cmd = regs[NEO_MV_CMD];
        mv_cmds.push_back(cmd);
        if (cmd & NEO_MV_COPY) {
            uint32_t src = r32(NEO_CP_SRC), dst = r32(NEO_CP_DST), len = r32(NEO_CP_LEN);
            int mode = cmd & 3;
            if ((src | dst | len) & 15) bad_align = true;
            for (uint32_t i = 0; i < len; i++) {
                uint32_t d = dst + i;
                bool w = mode == 0 || (mode == 1 && (d & 3) < 2) || (mode == 2 && (d & 3) >= 2);
                if (w) ddr.at(d - 0x01000000u) = ddr.at(src + i - 0x01000000u);
            }
            copies++;
        } else if (cmd & NEO_MV_SAVE) {                                 // a save of the card or the XRAM: the RAM's content comes out into its image
            uint32_t base = NEO_W_IMG + ((cmd & 3) == NEO_MV_XRAM ? 0x22000u : 0x20000u), n = (cmd & 3) == NEO_MV_XRAM ? 0x2000 : 0x800;
            for (uint32_t i = 0; i < n; i++) ddr.at(base + i) = (uint8_t)(0xA0 + (i & 15));
        }
        regs[NEO_MV_DONE]++;
    }
};

static std::vector<uint8_t> bytes(size_t n, uint32_t seed)
{
    std::vector<uint8_t> v(n);
    uint32_t x = seed * 2654435761u + 1;
    for (size_t i = 0; i < n; i++) { x ^= x << 13; x ^= x >> 17; x ^= x << 5; v[i] = (uint8_t)x; }
    return v;
}

static const char *XML =
    "<?xml version=\"1.0\"?>\n"
    "<romsets>\n"
    "  <!-- <romset name=\"hidden\" pvc=\"1\"/> a commented entry is no entry -->\n"
    "  <romset name=\"aoft\" pcm=\"1\" altname=\"Art of Fighting > test\" publisher=\"SNK\" year=\"1992\">\n"
    "    <file name=\"p1.p1\" type=\"P\" index=\"4\" offset=\"0\"/>\n"
    "    <file name=\"s1.s1\" type=\"S\" index=\"8\" offset=\"0\"/>\n"
    "    <file name=\"c1.c1\" type=\"C\" index=\"64\" offset=\"0\"/>\n"
    "    <file name=\"c2.c2\" type=\"C\" index=\"65\" offset=\"0\"/>\n"
    "    <file name=\"c3.c3\" index=\"68\"/>\n"
    "    <file name=\"c4.c4\" index=\"69\"/>\n"
    "    <file name=\"c1.c1\" index=\"72\" offset=\"0x100000\"/>\n"
    "    <file name=\"m1.m1\" index=\"9\"/>\n"
    "    <file name=\"v1.v1\" index=\"16\"/>\n"
    "    <file name=\"v2.v2\" index=\"20\" offset=\"0x100\" length=\"0x1000\"/>\n"
    "  </romset>\n"
    "  <romset name=\"kof2000,kof2000n\" sma=\"4\" cmc=\"2\" rom_wait=\"0\" p_wait=\"1\" altname=\"two names\"/>\n"
    "  <romset name=\"svct\" pvc=\"1\" xram=\"1\" ms5p=\"1\" ct0=\"1\" altname=\"chips\"/>\n"
    "  <romset name=\"darksoft\" altname=\"no files\"/>\n"
    "</romsets>\n";

// the oracles: the core's address maps
// MiSTer's loader (Main_MiSTer neogeo_loader.cpp, load_crom_to_mem + spr_convert_skp), relative to CROM_START: file word j goes to word 2 * i + slot of the pair's region with
// i = (j & ~31) | ((j & 15) << 1) | (((j >> 4) & 1) ^ 1) (the inverse of out[i] = in[(i & ~31) | ((i >> 1) & 15) | (((i & 1) ^ 1) << 4)]) and slot = (index ^ 1) & 1: c1 (even index) fills the odd words
static uint32_t crom_addr(uint32_t pair, uint32_t parity, uint32_t a)
{
    uint32_t j = a >> 1, i = (j & ~31u) | ((j & 15u) << 1) | (((j >> 4) & 1u) ^ 1u);
    return (pair << 20) + 4 * i + 2 * (parity ^ 1u) + (a & 1);
}
// a .neo C part: spr_bswap (the middle two bytes of every four) then spr_convert_dbl, out[i] = in[(i & ~63) | ((i ^ 1) & 1) | ((i >> 1) & 0x1E) | (((i & 2) ^ 2) << 4)] on 16 bit words
static std::vector<uint8_t> neo_c_oracle(const std::vector<uint8_t> &c)
{
    std::vector<uint8_t> sw(c);
    for (size_t k = 0; k + 4 <= sw.size(); k += 4) std::swap(sw[k + 1], sw[k + 2]);
    std::vector<uint8_t> out(sw.size());
    for (size_t i = 0; i < sw.size() / 2; i++) {
        size_t src = (i & ~(size_t)63) | ((i ^ 1) & 1) | ((i >> 1) & 0x1E) | (((i & 2) ^ 2) << 4);
        out[2 * i] = sw[2 * src]; out[2 * i + 1] = sw[2 * src + 1];
    }
    return out;
}
static int blk(int k) { static const int b[4] = { 2, 3, 0, 1 }; return b[k]; }                                                  // DEV_NOTES: the fix tile's column blocks 2, 3, 0, 1

static void put(FakeFs &fs, const char *path, const std::vector<uint8_t> &v) { fs.put(path, v); }

int main()
{
    // ---- romsets.xml
    {
        FakeFs fs;
        fs.put("/sd/roms/neogeo/romsets.xml", std::vector<uint8_t>(XML, XML + strlen(XML)));
        NeoSetInfo a, k, s, d, none, hidden;
        CHECK(neo_xml_find(&fs, "/sd/roms/neogeo/romsets.xml", "AOFT", &a));
        CHECK(a.found && a.pcm == 1 && a.nfiles == 10 && a.rom_wait == -1 && a.p_wait == -1);
        CHECK_EQ(a.f[0].index, 4);
        CHECK_STR(a.f[0].name, "p1.p1");
        CHECK_EQ(a.f[6].index, 72);
        CHECK_EQ(a.f[6].offset, 0x100000u);
        CHECK_EQ(a.f[9].offset, 0x100u);
        CHECK_EQ(a.f[9].size, 0x1000u);                                    // "length" is "size"
        CHECK(neo_xml_find(&fs, "/sd/roms/neogeo/romsets.xml", "kof2000n", &k));
        CHECK(k.found && k.sma == 4 && k.cmc == 2 && k.rom_wait == 0 && k.p_wait == 1 && k.nfiles == 0);
        CHECK(neo_xml_find(&fs, "/sd/roms/neogeo/romsets.xml", "svct", &s));
        CHECK(s.found && s.pvc && s.xram && s.ms5p && s.ct0);
        CHECK(neo_xml_find(&fs, "/sd/roms/neogeo/romsets.xml", "darksoft", &d));
        CHECK(d.found && d.nfiles == 0);
        CHECK(neo_xml_find(&fs, "/sd/roms/neogeo/romsets.xml", "nosuch", &none));
        CHECK(!none.found);
        CHECK(neo_xml_find(&fs, "/sd/roms/neogeo/romsets.xml", "hidden", &hidden));
        CHECK(!hidden.found);                                              // inside a comment
        CHECK(!neo_xml_find(&fs, "/sd/roms/neogeo/nofile.xml", "aoft", &none));
        // the chip word (neogeo.sv cfg): ms5p 17, xram 18, adpcma_ext 19, P chip 22:20 (PVC 2, SMA n = n + 2), pcm 23, ct0 / link 25:24, CMC 27:26, ROM wait 28, P wait 30:29
        CHECK_EQ(neo_cfg_word(s, false), 0x20000u | 0x40000u | (2u << 20) | (1u << 24) | (1u << 28) | (2u << 29));      // no wait said: one ROM wait, two P waits
        CHECK_EQ(neo_cfg_word(k, false), (6u << 20) | (2u << 26) | (0u << 28) | (1u << 29));
        CHECK_EQ(neo_cfg_word(a, true), (1u << 19) | (1u << 23) | (1u << 28) | (2u << 29));
    }
    // ---- a folder set: below the CPU's limit
    {
        NeoIo io; FakeFs fs; CoreCtx c; memset(&c, 0, sizeof(c)); c.io = &io; c.fs = &fs;
        fs.put("/sd/roms/neogeo/romsets.xml", std::vector<uint8_t>(XML, XML + strlen(XML)));
        std::vector<uint8_t> p1 = bytes(0x10000, 1), s1 = bytes(0x4000, 2), m1 = bytes(0x8000, 3), v1 = bytes(0x20000, 4), v2 = bytes(0x2000, 5);
        std::vector<uint8_t> cc[4] = { bytes(0x20000, 11), bytes(0x20000, 12), bytes(0x20000, 13), bytes(0x20000, 14) };
        const char *d = "/sd/games/aoft";
        put(fs, "/sd/games/aoft/p1.p1", p1); put(fs, "/sd/games/aoft/s1.s1", s1); put(fs, "/sd/games/aoft/m1.m1", m1);
        put(fs, "/sd/games/aoft/v1.v1", v1); put(fs, "/sd/games/aoft/v2.v2", v2);
        put(fs, "/sd/games/aoft/c1.c1", cc[0]); put(fs, "/sd/games/aoft/c2.c2", cc[1]); put(fs, "/sd/games/aoft/c3.c3", cc[2]); put(fs, "/sd/games/aoft/c4.c4", cc[3]);
        NeoSetInfo info;
        CHECK(neo_xml_find(&fs, "/sd/roms/neogeo/romsets.xml", "aoft", &info));
        static NeoParts parts;
        char msg[200];
        CHECK_EQ(neo_parts_xml(&fs, d, info, &parts, msg, sizeof(msg)), 0);
        CHECK_EQ(parts.n, 10);
        // the entry that starts behind the end of its file loads nothing; the one with offset and length takes that slice
        CHECK_EQ(parts.p[6].size, 0u);
        CHECK_EQ(parts.p[9].src_off, 0x100u);
        CHECK_EQ(parts.p[9].size, 0x1000u);
        NeoPlan pl;
        const uint32_t ROM = 0x01300000u, M1 = 0x010A0000u;
        CHECK_EQ(neo_plan(parts, ROM, M1, &pl, msg, sizeof(msg)), 0);
        CHECK_EQ(pl.c_start, 3);                                           // P1 only: the sprites follow at 3 MB
        CHECK_EQ(pl.p2_mask, 0u);
        CHECK_EQ(pl.c_mask, 0x3FFFFFu);                                    // pairs 0 and 2 of 128 KB files: 2 MB + 256 KB of addresses -> 4 MB
        CHECK_EQ(pl.m_mask, 0x7FFFu);
        CHECK(!pl.adpcma_ext);                                             // pcm set, but the V ROM stays inside 16 MB
        CHECK_EQ(pl.v1_mask, 0x3FFFFFu);                                   // index 20 is n = 4 of the first V space: 2 MB + 4 KB -> 4 MB
        CHECK_EQ(pl.v2_mask, 0u);                                          // no separate ADPCM-B ROM
        CHECK_EQ(pl.cfg, neo_cfg_word(info, false));
        CHECK_EQ(neo_load(&c, parts, pl, msg, sizeof(msg)), 0);
        CHECK(!io.cpu_over && !io.bad_align);
        // P at $200000, S rearranged at $80000 (tile = 32 bytes: out[line * 4 + k] = in[blk(k) * 8 + line]), M at m1_base
        bool ok = true;
        for (size_t i = 0; i < p1.size(); i++) ok &= io.at(ROM + 0x200000 + i) == p1[i];
        CHECK(ok);
        ok = true;
        for (size_t t = 0; t < s1.size() / 32; t++)
            for (int line = 0; line < 8; line++)
                for (int k = 0; k < 4; k++) ok &= io.at(ROM + 0x80000 + t * 32 + line * 4 + k) == s1[t * 32 + blk(k) * 8 + line];
        CHECK(ok);
        // the table of DEV_NOTES.md literally: line 0 is bytes 10 18 00 08 of the tile, line 1 is 11 19 01 09
        CHECK_EQ(io.at(ROM + 0x80000 + 0), s1[0x10]);
        CHECK_EQ(io.at(ROM + 0x80000 + 3), s1[0x08]);
        CHECK_EQ(io.at(ROM + 0x80000 + 4), s1[0x11]);
        CHECK_EQ(io.at(ROM + 0x80000 + 7), s1[0x09]);
        ok = true;
        for (size_t i = 0; i < m1.size(); i++) ok &= io.at(M1 + i) == m1[i];
        CHECK(ok);
        // V: index 16 at 0 of the first V space, index 20 at 4 * 512 KB = 2 MB
        ok = true;
        for (size_t i = 0; i < v1.size(); i++) ok &= io.at(pl.v1_base + i) == v1[i];
        CHECK(ok);
        ok = true;
        for (size_t i = 0; i < 0x1000; i++) ok &= io.at(pl.v1_base + 0x200000 + i) == v2[0x100 + i];
        CHECK(ok);
        // C: every byte of the four files where MiSTer's loader puts it (c1 index 64 = pair 0 parity 0, c2 65 = pair 0 parity 1, c3 68 = pair 2 parity 0, c4 69)
        ok = true;
        const uint32_t cbase = ROM + ((uint32_t)pl.c_start << 20);
        for (int f = 0; f < 4; f++) {
            uint32_t pair = (f / 2) * 2, parity = f & 1;
            for (size_t a = 0; a < cc[f].size(); a++) ok &= io.at(cbase + crom_addr(pair, parity, (uint32_t)a)) == cc[f][a];
        }
        CHECK(ok);
        CHECK_EQ(io.r32(NEO_ROM_BASE), ROM);
        CHECK_EQ(io.r32(NEO_M1_BASE), M1);
        CHECK_EQ(io.r32(NEO_C_MASK), 0x3FFFFFu);
        CHECK_EQ(io.r32(NEO_CFG), pl.cfg);
        CHECK_EQ(io.regs[NEO_C_START], 3);
        CHECK(io.copies > 0);                                              // the sprites go through the copy engine (the byte masks keep the partner's bytes)
    }
    // ---- a missing file, a Darksoft style entry, a set that does not fit
    {
        NeoIo io; FakeFs fs; char msg[300]; static NeoParts parts;
        fs.put("/sd/roms/neogeo/romsets.xml", std::vector<uint8_t>(XML, XML + strlen(XML)));
        put(fs, "/sd/games/aoft/p1.p1", bytes(0x1000, 1));
        NeoSetInfo info;
        CHECK(neo_xml_find(&fs, "/sd/roms/neogeo/romsets.xml", "aoft", &info));
        CHECK_EQ(neo_parts_xml(&fs, "/sd/games/aoft", info, &parts, msg, sizeof(msg)), 1);
        CHECK(strstr(msg, "s1.s1") != 0 && strstr(msg, "missing") != 0);
        CHECK(neo_xml_find(&fs, "/sd/roms/neogeo/romsets.xml", "darksoft", &info));
        CHECK_EQ(neo_parts_xml(&fs, "/sd/games/aoft", info, &parts, msg, sizeof(msg)), 1);
        CHECK(strstr(msg, "Darksoft") != 0);
        CHECK(neo_xml_find(&fs, "/sd/roms/neogeo/romsets.xml", "nosuch", &info));
        CHECK_EQ(neo_parts_xml(&fs, "/sd/games/aoft", info, &parts, msg, sizeof(msg)), 1);
        CHECK(strstr(msg, "no entry") != 0);
        // a plan alone: 24 MB of V ROM behind 96 MB of sprites does not fit 128 MB
        memset(&parts, 0, sizeof(parts));
        parts.n = 2;
        parts.p[0].kind = NK_C; parts.p[0].index = 64 + 2 * 90; parts.p[0].size = 0x100000;
        parts.p[1].kind = NK_V; parts.p[1].index = 16; parts.p[1].size = 0x1800000;
        NeoPlan pl;
        CHECK_EQ(neo_plan(parts, 0x01300000u, 0x010A0000u, &pl, msg, sizeof(msg)), 1);
        CHECK(strstr(msg, "does not fit") != 0);
        parts.p[1].size = 0x100000;
        CHECK_EQ(neo_plan(parts, 0x01300000u, 0x010A0000u, &pl, msg, sizeof(msg)), 0);
    }
    // ---- sprites above 64 MB: the CPU cannot write there, the copy engine does
    {
        NeoIo io; FakeFs fs; CoreCtx c; memset(&c, 0, sizeof(c)); c.io = &io; c.fs = &fs;
        std::vector<uint8_t> c1 = bytes(0x8000, 21), c2 = bytes(0x8000, 22), pp = bytes(0x4000, 23);
        put(fs, "/sd/g/c1.c1", c1); put(fs, "/sd/g/c2.c2", c2); put(fs, "/sd/g/p.p1", pp);
        static NeoParts parts; memset(&parts, 0, sizeof(parts));
        auto add = [&](int kind, int index, const char *path, size_t n) {
            NeoPart &q = parts.p[parts.n++]; q.kind = (uint8_t)kind; q.index = index; q.size = (uint32_t)n; snprintf(q.path, sizeof(q.path), "%s", path);
        };
        add(NK_P, 4, "/sd/g/p.p1", pp.size());
        add(NK_C, 64 + 2 * 70, "/sd/g/c1.c1", c1.size());                // pair 70: 70 MB above the C ROM base
        add(NK_C, 64 + 2 * 70 + 1, "/sd/g/c2.c2", c2.size());
        NeoPlan pl; char msg[200];
        const uint32_t ROM = 0x01300000u;
        CHECK_EQ(neo_plan(parts, ROM, 0x010A0000u, &pl, msg, sizeof(msg)), 0);
        CHECK_EQ(neo_load(&c, parts, pl, msg, sizeof(msg)), 0);
        CHECK(!io.cpu_over && !io.bad_align);
        CHECK(io.copies >= 2);
        bool ok = true;
        const uint32_t cbase = ROM + (3u << 20);
        CHECK(cbase + (70u << 20) > 0x04000000u);                          // really beyond the CPU
        for (size_t a = 0; a < c1.size(); a++) ok &= io.at(cbase + crom_addr(70, 0, (uint32_t)a)) == c1[a];
        for (size_t a = 0; a < c2.size(); a++) ok &= io.at(cbase + crom_addr(70, 1, (uint32_t)a)) == c2[a];
        CHECK(ok);
    }
    // ---- neo_put at the edges: below the CPU's limit straight, across it and above it through the staging megabyte and the copy engine
    {
        NeoIo io; FakeFs fs; CoreCtx c; memset(&c, 0, sizeof(c)); c.io = &io; c.fs = &fs;
        std::vector<uint8_t> d = bytes(4096, 77);
        const uint32_t at[3] = { 0x02000000u, NEO_CPU_LIMIT - 2048, 0x05000000u };
        for (int k = 0; k < 3; k++) {
            uint32_t before = io.copies;
            CHECK(neo_put(&c, at[k], d.data(), (uint32_t)d.size(), 0));
            bool ok = true;
            for (size_t i = 0; i < d.size(); i++) ok &= io.at(at[k] + (uint32_t)i) == d[i];
            CHECK(ok);
            CHECK_EQ(io.copies > before, k > 0);                           // only what reaches the CPU's limit needs the copy engine
        }
        CHECK(!io.cpu_over && !io.bad_align);
        // masks: mode 1 writes bytes 0,1 of every four and leaves 2,3
        std::vector<uint8_t> e(64, 0xEE);
        CHECK(neo_put(&c, 0x05000000u, e.data(), 64, 1));
        bool ok = true;
        for (int i = 0; i < 64; i++) ok &= io.at(0x05000000u + (uint32_t)i) == ((i & 3) < 2 ? 0xEE : d[i]);
        CHECK(ok);
    }
    // ---- a .neo file
    {
        NeoIo io; FakeFs fs; CoreCtx c; memset(&c, 0, sizeof(c)); c.io = &io; c.fs = &fs;
        std::vector<uint8_t> P = bytes(0x3000, 31), S = bytes(0x2000, 32), M = bytes(0x1000, 33), V1 = bytes(0x4000, 34), V2 = bytes(0x2000, 35), C = bytes(0x4000, 36);
        // the 68k's order at $100: "NEO-GEO", so the file is in the 68k's byte order and the application swaps it
        memcpy(&P[0x100], "NEO-GEO", 7);
        std::vector<uint8_t> f(4096, 0);
        memcpy(f.data(), "NEO\x01", 4);
        uint32_t sz[6] = { (uint32_t)P.size(), (uint32_t)S.size(), (uint32_t)M.size(), (uint32_t)V1.size(), (uint32_t)V2.size(), (uint32_t)C.size() };
        for (int i = 0; i < 6; i++) for (int b = 0; b < 4; b++) f[4 + 4 * i + b] = (uint8_t)(sz[i] >> (8 * b));
        for (auto *v : { &P, &S, &M, &V1, &V2, &C }) f.insert(f.end(), v->begin(), v->end());
        fs.put("/sd/g/neotest.neo", f);
        NeoSetInfo none; memset(&none, 0, sizeof(none)); none.rom_wait = none.p_wait = -1; snprintf(none.name, sizeof(none.name), "neotest");
        static NeoParts parts; char msg[200];
        CHECK_EQ(neo_parts_neo(&fs, "/sd/g/neotest.neo", none, &parts, msg, sizeof(msg)), 0);
        CHECK(parts.p_swap);
        CHECK_EQ(parts.n, 6);
        NeoPlan pl;
        const uint32_t ROM = 0x01300000u, M1 = 0x010A0000u;
        CHECK_EQ(neo_plan(parts, ROM, M1, &pl, msg, sizeof(msg)), 0);
        CHECK_EQ(neo_load(&c, parts, pl, msg, sizeof(msg)), 0);
        bool ok = true;
        for (size_t i = 0; i + 1 < P.size(); i += 2) ok &= io.at(ROM + 0x200000 + i) == P[i + 1] && io.at(ROM + 0x200000 + i + 1) == P[i];
        CHECK(ok);
        CHECK_EQ(io.at(ROM + 0x200000 + 0x100), (uint8_t)'E');            // "NEO-GEO" swapped: E N - O E G O
        ok = true;
        for (size_t i = 0; i < V1.size(); i++) ok &= io.at(pl.v1_base + i) == V1[i];
        for (size_t i = 0; i < V2.size(); i++) ok &= io.at(pl.v2_base + i) == V2[i];
        CHECK(ok);
        // the C ROM of a .neo alternates C1 and C2 bytes; MiSTer's loader swaps the middle two bytes of every four and permutes the words in blocks of 64 (spr_convert_dbl)
        ok = true;
        const uint32_t cbase = ROM + ((uint32_t)pl.c_start << 20);
        {
            std::vector<uint8_t> want = neo_c_oracle(C);
            for (size_t k = 0; k < C.size(); k++) ok &= io.at(cbase + k) == want[k];
        }
        CHECK(ok);
        CHECK_EQ(pl.c_mask, 0x3FFFu);
        // a P ROM in the file order of MAME ("EN-OEGO" at $100) is taken as it is
        std::vector<uint8_t> f2 = f;
        memcpy(&f2[4096 + 0x100], "EN-OEGO", 7);
        fs.put("/sd/g/swapped.neo", f2);
        CHECK_EQ(neo_parts_neo(&fs, "/sd/g/swapped.neo", none, &parts, msg, sizeof(msg)), 0);
        CHECK(!parts.p_swap);
        // a file that is no .neo, and one that is shorter than its header says
        fs.put("/sd/g/bad.neo", bytes(5000, 40));
        CHECK_EQ(neo_parts_neo(&fs, "/sd/g/bad.neo", none, &parts, msg, sizeof(msg)), 1);
        std::vector<uint8_t> f3(f.begin(), f.begin() + 8000);
        fs.put("/sd/g/short.neo", f3);
        CHECK_EQ(neo_parts_neo(&fs, "/sd/g/short.neo", none, &parts, msg, sizeof(msg)), 1);
        CHECK(strstr(msg, "the header says") != 0);
    }
    // ---- the descriptor: the BIOS choice, the order of a start, a game, the saves
    {
        NeoIo io; FakeFs fs; PxRec px;
        CoreCtx c; memset(&c, 0, sizeof(c));
        c.desc = &neogeo_desc; c.io = &io; c.fs = &fs;
        Settings st(neogeo_desc.settings, neogeo_desc.nsettings, neogeo_desc.store, &fs, "/sd/neogeo.cfg", 0);
        st.load();
        c.settings = &st;
        Video vid(neogeo_desc.video, &px, &io);
        c.video = &vid;
        char msg[300];
        const uint32_t ROM = NEO_DDR_BASE + NEO_W_ROM;
        std::vector<uint8_t> bios_mvs = bytes(0x20000, 51), bios_aes = bytes(0x20000, 52), bios_uni = bytes(0x20000, 53), lo = bytes(0x10000, 54), sfix = bytes(0x20000, 55);
        // the ROM specs: the three BIOS are alternatives, the zoom table and the fix ROM are required
        CHECK_EQ(neogeo_desc.nroms, 5);
        int required = 0, alt = 0;
        for (int i = 0; i < neogeo_desc.nroms; i++) { required += neogeo_desc.roms[i].required; alt += neogeo_desc.roms[i].set != 0; }
        CHECK_EQ(required, 2);
        CHECK_EQ(alt, 3);
        CHECK_EQ(neogeo_desc.init(&c, msg, sizeof(msg)), 0);
        CHECK_EQ(io.log.front().reg, NEO_CTRL);
        CHECK_EQ(io.log.front().v, NEO_HOLD);
        CHECK_STR(io.events.front().c_str(), "mode_reset");
        CHECK_EQ(io.r32(NEO_ROM_BASE), ROM);
        CHECK_EQ(io.r32(NEO_M1_BASE), NEO_DDR_BASE + NEO_W_M1);
        OpResult r;
        OpIn bad = in_blob("data", bios_mvs.data(), 1000);
        CHECK_EQ(ops_call(&c, "neogeo.put_bios_mvs", &bad, 1, &r), OPE_FAILED);
        CHECK(strstr(r.msg, "131072") != 0);
        OpIn i1 = in_blob("data", bios_mvs.data(), (uint32_t)bios_mvs.size()), i2 = in_blob("data", bios_aes.data(), (uint32_t)bios_aes.size()), i3 = in_blob("data", bios_uni.data(), (uint32_t)bios_uni.size());
        CHECK_EQ(ops_call(&c, "neogeo.put_bios_mvs", &i1, 1, &r), OPE_OK);
        CHECK_EQ(ops_call(&c, "neogeo.put_bios_aes", &i2, 1, &r), OPE_OK);
        CHECK_EQ(ops_call(&c, "neogeo.put_bios_uni", &i3, 1, &r), OPE_OK);
        OpIn il = in_blob("data", lo.data(), (uint32_t)lo.size()), is = in_blob("data", sfix.data(), (uint32_t)sfix.size());
        CHECK_EQ(ops_call(&c, "neogeo.put_lo", &il, 1, &r), OPE_OK);
        CHECK_EQ(ops_call(&c, "neogeo.put_sfix", &is, 1, &r), OPE_OK);
        bool ok = true;
        for (int t = 0; t < 0x20000 / 32; t++)
            for (int line = 0; line < 8; line++)
                for (int k = 0; k < 4; k++) ok &= io.at(ROM + 0x20000 + t * 32 + line * 4 + k) == sfix[t * 32 + blk(k) * 8 + line];
        CHECK(ok);
        // the system ROM: Universe BIOS by default; the original one of the system type when asked
        auto sysrom = [&](const std::vector<uint8_t> &want) {
            bool same = true;
            for (size_t i = 0; i < want.size(); i++) same &= io.at(ROM + (uint32_t)i) == want[i];
            return same;
        };
        CHECK_EQ(neogeo_desc.release(&c, msg, sizeof(msg)), 0);
        CHECK(sysrom(bios_uni));
        int ib = st.find("BIOS"), isys = st.find("System type");
        CHECK(ib >= 0 && isys >= 0);
        st.set(ib, 1); st.set(isys, 1);
        CHECK_EQ(neogeo_desc.release(&c, msg, sizeof(msg)), 0);
        CHECK(sysrom(bios_mvs));
        st.set(isys, 0);
        CHECK_EQ(neogeo_desc.release(&c, msg, sizeof(msg)), 0);
        CHECK(sysrom(bios_aes));
        // the zoom table went into the core once, before CTRL was released
        size_t n_lo = 0;
        for (uint8_t m : io.mv_cmds) n_lo += (m == NEO_MV_LO);
        CHECK_EQ(n_lo, 1u);
        int first_ctrl_rel = -1, first_go = -1;
        for (size_t i = 0; i < io.log.size(); i++) {
            if (io.log[i].reg == NEO_CTRL && io.log[i].v == 0 && first_ctrl_rel < 0) first_ctrl_rel = (int)i;
            if (io.log[i].reg == NEO_MV_GO && first_go < 0) first_go = (int)i;
        }
        CHECK(first_go >= 0 && first_go < first_ctrl_rel);
        // a game: a .neo file; no romsets.xml, so no chips (and the message says so)
        {
            std::vector<uint8_t> P = bytes(0x2000, 61), S = bytes(0x400, 62), M = bytes(0x400, 63), V1 = bytes(0x800, 64), C = bytes(0x1000, 65);
            std::vector<uint8_t> f(4096, 0);
            memcpy(f.data(), "NEO\x01", 4);
            uint32_t sz[6] = { (uint32_t)P.size(), (uint32_t)S.size(), (uint32_t)M.size(), (uint32_t)V1.size(), 0, (uint32_t)C.size() };
            for (int i = 0; i < 6; i++) for (int b = 0; b < 4; b++) f[4 + 4 * i + b] = (uint8_t)(sz[i] >> (8 * b));
            for (auto *v : { &P, &S, &M, &V1, &C }) f.insert(f.end(), v->begin(), v->end());
            fs.put("/usb0/games/mini.neo", f);
            const FileAction &act = neogeo_desc.filetypes[0].actions[0];
            CHECK_STR(neogeo_desc.filetypes[0].ext, ".neo");
            CHECK_EQ(ops_run_bound(&c, act.op, act.bind, act.nbind, "/usb0/games/mini.neo", &r), 0);
            CHECK(strstr(r.msg, "romsets.xml") != 0);
            CHECK(c.program_loaded && c.started);
            // the save: the backup RAM the machine wrote into the DDR2, the card out of the core, on the medium of the game
            for (int i = 0; i < 0x10000; i++) io.ddr.at(NEO_W_BACKUP + i) = (uint8_t)(i * 3);
            io.regs[NEO_STATUS] |= NEO_ST_DIRTY;
            CHECK_EQ(ops_call(&c, "neogeo.service", 0, 0, &r), OPE_OK);
            io.advance(2500000);
            CHECK_EQ(ops_call(&c, "neogeo.service", 0, 0, &r), OPE_OK);
            io.advance(2500000);
            CHECK_EQ(ops_call(&c, "neogeo.service", 0, 0, &r), OPE_OK);
            auto it = fs.files.find("/usb0/saves/neogeo/mini.sav");
            CHECK(it != fs.files.end());
            if (it != fs.files.end()) {
                CHECK_EQ(it->second.size(), 0x12000u);
                bool same = true;
                for (int i = 0; i < 0x10000; i++) same &= it->second[i] == (uint8_t)(i * 3);
                CHECK(same);
                CHECK_EQ(it->second[0x10000], 0xA0);                       // the card, as the model's core hands it out
                // another game, with a save of its own, loads it into the DDR2 before the machine runs
                fs.put("/usb0/games/other.neo", f);
                std::vector<uint8_t> sv(0x12000, 0);
                for (int i = 0; i < 0x10000; i++) sv[i] = (uint8_t)(i * 5 + 1);
                sv[0x10000] = 0x77;
                fs.put("/usb0/saves/neogeo/other.sav", sv);
                CHECK_EQ(ops_run_bound(&c, act.op, act.bind, act.nbind, "/usb0/games/other.neo", &r), 0);
                same = true;
                for (int i = 0; i < 0x10000; i++) same &= io.ddr.at(NEO_W_BACKUP + i) == (uint8_t)(i * 5 + 1);
                CHECK(same);
                CHECK_EQ(io.ddr.at(NEO_W_MEMCARD), 0x77);
                CHECK(same);
            }
            // T148: with a hand-over (cor_path) the save belongs in the core's folder, romsets.xml is copied into its roms folder once; the older places are read, not written
            strcpy(c.cor_path, "/sd/cores/neogeo.cor");
            fs.put("/sd/roms/neogeo/romsets.xml", std::vector<uint8_t>(XML, XML + strlen(XML)));
            fs.put("/usb0/games/third.neo", f);
            std::vector<uint8_t> sv3(0x12000, 0);
            sv3[0x10000] = 0x66;
            fs.put("/usb0/saves/neogeo/third.sav", sv3);
            CHECK_EQ(ops_run_bound(&c, act.op, act.bind, act.nbind, "/usb0/games/third.neo", &r), 0);
            CHECK(fs.files.find("/sd/cores/neogeo/roms/romsets.xml") != fs.files.end());                 // copied, verified
            CHECK(fs.files.find("/sd/roms/neogeo/romsets.xml") != fs.files.end());                       // the original is untouched
            CHECK_EQ(io.ddr.at(NEO_W_MEMCARD), 0x66);                                                    // the save of the older place was taken over
            io.regs[NEO_STATUS] |= NEO_ST_DIRTY;
            for (int k = 0; k < 3; k++) {
                CHECK_EQ(ops_call(&c, "neogeo.service", 0, 0, &r), OPE_OK);
                io.advance(2500000);
            }
            auto ns = fs.files.find("/sd/cores/neogeo/saves/third.sav");
            CHECK(ns != fs.files.end());                                                                 // written to the core's folder
            CHECK(fs.files.find("/usb0/saves/neogeo/third.sav")->second[0x10000] == 0x66);               // the old file stays as it was
            CHECK(fs.files.find("/usb0/saves/neogeo/mini.sav")->second.size() == 0x12000u);
            c.cor_path[0] = 0;
            // T180 D4 / D1 (S7): a save the game owes is in its file before the game is let go (reset, reload, restart, another game); a medium that refuses keeps the
            // game loaded and stops the exit; a save that did not change is no reason to stop
            {
                fs.put("/usb0/games/fourth.neo", f);
                fs.put("/usb0/games/fifth.neo", f);
                CHECK_EQ(ops_run_bound(&c, act.op, act.bind, act.nbind, "/usb0/games/fourth.neo", &r), 0);
                io.regs[NEO_STATUS] &= (uint8_t)~NEO_ST_DIRTY;
                char m[300];
                CHECK(!neogeo_desc.media_pending(&c));
                int mut = fs.mutations;
                fs.read_only = true;                                                                     // a card that cannot be written: nothing changed, nothing to stop for
                CHECK_EQ(media_writeback(&c, WB_WHY_RESET, m, sizeof(m)), 0);
                CHECK_EQ(fs.mutations, mut);
                io.events.clear();
                CHECK_EQ(boot_cold_reset(&c, m, sizeof(m)), 0);
                fs.read_only = false;
                io.regs[NEO_STATUS] |= NEO_ST_DIRTY;                                                      // the game wrote its card
                for (int i = 0; i < 0x10000; i++) io.ddr.at(NEO_W_BACKUP + i) = (uint8_t)(i * 7 + 2);
                CHECK(neogeo_desc.media_pending(&c));
                fs.read_only = true;
                CHECK(media_writeback(&c, WB_WHY_RESET, m, sizeof(m)) != 0);
                CHECK(strstr(m, "fourth.sav") != 0 && strstr(m, "stays loaded") != 0);
                io.regs[NEO_STATUS] &= (uint8_t)~NEO_ST_DIRTY;                                            // the core's flag was taken; the file does not have it
                CHECK(neogeo_desc.media_pending(&c));
                io.events.clear();
                CHECK(boot_cold_reset(&c, m, sizeof(m)) != 0);
                CHECK(boot_reload(&c, m, sizeof(m)) != 0);
                CHECK(boot_restart(&c, m, sizeof(m)) != 0);
                CHECK(ops_run_bound(&c, act.op, act.bind, act.nbind, "/usb0/games/fifth.neo", &r) != 0);   // D1: another game does not replace this one
                CHECK(c.program_loaded);
                CHECK(io.events.empty());                                                                 // the machine was never held
                fs.read_only = false;
                CHECK_EQ(media_writeback(&c, WB_WHY_RESET, m, sizeof(m)), 0);
                auto sv4 = fs.files.find("/usb0/saves/neogeo/fourth.sav");
                CHECK(sv4 != fs.files.end() && sv4->second.size() == 0x12000u && sv4->second[5] == (uint8_t)(5 * 7 + 2));
                CHECK(!neogeo_desc.media_pending(&c));
                CHECK_EQ(ops_run_bound(&c, act.op, act.bind, act.nbind, "/usb0/games/fifth.neo", &r), 0);
            }
        }
    }
    DONE("test_neogeo");
}
